-- CREATE RULE analyses its condition and actions as PostgreSQL does: OLD
-- and NEW visibility, column and operator resolution, assignments and the
-- RETURNING list against the rule's relation. A multi-row VALUES action
-- converts each item to its target column's type; RETURNING lists read the
-- returned rows as rows of the rule's relation; a SELECT action sends rows.
CREATE TABLE src289 (a int, b text);
CREATE TABLE dst289 (x text, y int, z numeric(5,1) DEFAULT 9.5);
CREATE RULE v289 AS ON INSERT TO src289 DO ALSO INSERT INTO dst289
  VALUES ('1'::text, 3, 1.26), (2, DEFAULT, '2.04'), ('2026-01-01'::date - '2020-01-01'::date, 4.6, 7);
INSERT INTO src289 VALUES (1, 'a');
SELECT * FROM dst289 ORDER BY x;
CREATE TABLE dst289b (x int, d date);
CREATE RULE w289 AS ON INSERT TO src289 DO ALSO INSERT INTO dst289b (d, x)
  VALUES ('2020-01-01', '5'), (date '2021-02-03', 6.7);
INSERT INTO src289 VALUES (2, 'b');
SELECT * FROM dst289b ORDER BY x;
DROP RULE v289 ON src289;
DROP RULE w289 ON src289;
CREATE TABLE pt289 (p point);
CREATE RULE bad289 AS ON INSERT TO src289 DO ALSO INSERT INTO pt289 VALUES (1), ('(1,2)');
CREATE RULE bad289 AS ON INSERT TO src289 DO ALSO INSERT INTO pt289 VALUES (1);
CREATE RULE bad289 AS ON INSERT TO src289 DO ALSO INSERT INTO dst289 (nope) VALUES (1);
CREATE RULE bad289 AS ON INSERT TO src289 DO ALSO INSERT INTO pt289 SELECT 1;
CREATE RULE bad289 AS ON INSERT TO src289 DO ALSO INSERT INTO dst289 (y) VALUES (new.b);
CREATE RULE bad289 AS ON INSERT TO src289 DO ALSO DELETE FROM dst289 WHERE y = new.b;
CREATE RULE bad289 AS ON INSERT TO src289 DO ALSO UPDATE dst289 SET y = new.nope;
CREATE RULE bad289 AS ON INSERT TO src289 DO ALSO SELECT new.a || 1 + now();
CREATE RULE bad289 AS ON INSERT TO src289 DO ALSO SELECT * FROM nosuch289;
-- OLD and NEW in conditions and actions.
CREATE RULE c289 AS ON INSERT TO src289 WHERE old.a > 1 DO ALSO SELECT 1;
CREATE RULE c289 AS ON DELETE TO src289 WHERE new.a > 1 DO ALSO SELECT 1;
CREATE RULE c289 AS ON INSERT TO src289 DO ALSO SELECT new.nope;
CREATE RULE c289 AS ON INSERT TO src289 DO ALSO SELECT old.a;
CREATE RULE c289 AS ON INSERT TO src289 DO ALSO SELECT 1 FROM src289 WHERE src289.a = old.a;
CREATE RULE c289 AS ON INSERT TO src289 DO ALSO SELECT (SELECT old.a);
CREATE RULE c289 AS ON INSERT TO src289 WHERE src289.a > 1 DO ALSO SELECT 1;
CREATE RULE c289 AS ON INSERT TO src289 WHERE new.zz > 1 DO ALSO SELECT 1;
CREATE RULE c289 AS ON DELETE TO src289 DO ALSO SELECT new.a;
CREATE RULE c289 AS ON INSERT TO src289 WHERE new.a DO ALSO SELECT 1;
CREATE RULE c289 AS ON INSERT TO src289 WHERE new.a + 'x' > 0 DO ALSO SELECT 1;
CREATE RULE c289 AS ON UPDATE TO src289 DO ALSO SELECT old.zz;
CREATE RULE c289 AS ON UPDATE TO src289 DO ALSO SELECT x.a FROM src289 x WHERE x.b = old.a;
CREATE RULE c289 AS ON UPDATE TO src289 WHERE a > 1 DO ALSO SELECT 1;
CREATE RULE c289 AS ON UPDATE TO src289 WHERE src289.a > 1 DO ALSO SELECT 1;
CREATE RULE c289 AS ON DELETE TO src289 WHERE src289.a > 1 DO ALSO SELECT 1;
CREATE RULE c289 AS ON INSERT TO src289 WHERE dst289.y > 1 DO ALSO SELECT 1;
CREATE RULE c289 AS ON INSERT TO src289 WHERE zz > 1 DO ALSO SELECT 1;
CREATE RULE c289 AS ON INSERT TO src289 DO ALSO SELECT a;
CREATE RULE c289 AS ON INSERT TO src289 DO ALSO SELECT src289.a;
CREATE RULE c289 AS ON INSERT TO src289 WHERE count(*) > 1 DO ALSO SELECT 1;
CREATE RULE c289 AS ON INSERT TO src289 DO ALSO INSERT INTO dst289b VALUES (old.a);
CREATE RULE c289 AS ON DELETE TO src289 DO ALSO DELETE FROM dst289b WHERE x = new.a;
CREATE RULE c289 AS ON INSERT TO src289 WHERE a > 100 DO ALSO SELECT new.a * 2 AS dbl, (SELECT count(*) FROM dst289b WHERE dst289b.x = new.a);
CREATE RULE d289 AS ON UPDATE TO src289 WHERE old.a <> new.a DO ALSO INSERT INTO dst289b SELECT old.a + new.a;
-- A SELECT action's rows reach the client unless the statement returns rows.
CREATE TABLE sel289 (a int);
CREATE RULE sel289 AS ON INSERT TO sel289 DO ALSO SELECT new.a * 10 AS ten;
INSERT INTO sel289 VALUES (4), (5);
INSERT INTO sel289 VALUES (6) RETURNING a;
CREATE VIEW selv289 AS SELECT a FROM sel289;
CREATE RULE selv289 AS ON INSERT TO selv289 DO INSTEAD INSERT INTO sel289 VALUES (new.a + 1);
INSERT INTO selv289 VALUES (7);
-- RETURNING lists of rule actions.
CREATE TABLE rt289 (id int, v text);
CREATE VIEW rv289 AS SELECT id, v FROM rt289;
CREATE RULE r289 AS ON INSERT TO rv289 DO INSTEAD INSERT INTO rt289 VALUES (new.id, new.v) RETURNING id, v, 1;
CREATE RULE r289 AS ON INSERT TO rv289 DO INSTEAD INSERT INTO rt289 VALUES (new.id, new.v) RETURNING id;
CREATE RULE r289 AS ON INSERT TO rv289 DO INSTEAD INSERT INTO rt289 VALUES (new.id, new.v) RETURNING v, id;
CREATE RULE r289 AS ON INSERT TO rv289 DO INSTEAD INSERT INTO rt289 VALUES (new.id, new.v) RETURNING id::int8, v;
CREATE RULE r289 AS ON INSERT TO rv289 DO INSTEAD INSERT INTO rt289 VALUES (new.id, new.v) RETURNING *;
CREATE RULE u289 AS ON UPDATE TO rv289 DO INSTEAD UPDATE rt289 SET v = new.v WHERE id = old.id RETURNING old.*;
CREATE RULE u289 AS ON UPDATE TO rv289 DO INSTEAD UPDATE rt289 SET v = new.v FROM rt289 x WHERE rt289.id = old.id RETURNING *;
CREATE RULE del289 AS ON DELETE TO rv289 DO INSTEAD DELETE FROM rt289 WHERE id = old.id RETURNING old.id, 'x';
INSERT INTO rv289 VALUES (1, 'r') RETURNING v;
UPDATE rv289 SET v = 'u' WHERE id = 1 RETURNING id, v;
DELETE FROM rv289 WHERE id = 1 RETURNING *;
CREATE TABLE rt289b (id int, v varchar(3));
CREATE VIEW rv289b AS SELECT id, v FROM rt289b;
CREATE RULE r289b AS ON INSERT TO rv289b DO INSTEAD INSERT INTO rt289 VALUES (new.id, new.v) RETURNING id, v;
CREATE TABLE tt289 (id int, v text);
CREATE VIEW ww289 AS SELECT id AS xid, v AS xv FROM tt289;
CREATE RULE ww289 AS ON INSERT TO ww289 DO INSTEAD
  INSERT INTO tt289 VALUES (new.xid, 'x'), (new.xid + 10, 'y') RETURNING new.xid, tt289.v;
CREATE RULE ww289 AS ON INSERT TO ww289 DO INSTEAD
  INSERT INTO tt289 VALUES (new.xid, 'x'), (new.xid + 10, 'y') RETURNING new.id, tt289.v;
INSERT INTO ww289 VALUES (5, 'q') RETURNING *;
INSERT INTO ww289 VALUES (6, 'q') RETURNING xv;
CREATE VIEW w5289 AS SELECT id AS xid, v AS xv FROM tt289;
CREATE RULE w5289 AS ON UPDATE TO w5289 DO INSTEAD
  UPDATE tt289 SET v = new.xv WHERE id = old.xid RETURNING old.xid, new.xv;
UPDATE w5289 SET xv = 'zz' WHERE xid = 5 RETURNING *;
UPDATE w5289 SET xv = 'zy' WHERE xid = 6 RETURNING xv || '!', xid * 2;
WITH c AS (INSERT INTO rv289 VALUES (2, 's') RETURNING *) SELECT * FROM c;
SELECT * FROM rt289 ORDER BY id;
-- A data-modifying WITH query must rewrite to exactly one statement.
CREATE TABLE log289 (a int);
CREATE TABLE w1289 (a int);
CREATE RULE w1289 AS ON INSERT TO w1289 DO ALSO INSERT INTO log289 VALUES (new.a);
WITH c AS (INSERT INTO w1289 VALUES (1) RETURNING *) SELECT * FROM c;
CREATE TABLE w2289 (a int);
CREATE RULE w2289 AS ON INSERT TO w2289 DO INSTEAD (INSERT INTO log289 VALUES (new.a); INSERT INTO log289 VALUES (new.a + 1));
WITH c AS (INSERT INTO w2289 VALUES (1)) SELECT 1;
CREATE TABLE w3289 (a int);
CREATE RULE w3289 AS ON INSERT TO w3289 DO INSTEAD NOTHING;
WITH c AS (INSERT INTO w3289 VALUES (1)) SELECT 1;
CREATE TABLE w4289 (a int);
CREATE RULE w4289 AS ON INSERT TO w4289 WHERE new.a > 0 DO INSTEAD INSERT INTO log289 VALUES (new.a);
WITH c AS (INSERT INTO w4289 VALUES (1)) SELECT 1;
SELECT * FROM log289;
